const t={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Надсилайте команди на екран FilaMind, вбудований у принтер."}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:"Командну шину підключено"}},down:{t:0,b:{t:2,i:[{t:3}],s:"Підключення до командної шини…"}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:"Показати на екрані"}},status:{t:0,b:{t:2,i:[{t:3}],s:"Стан"}},control:{t:0,b:{t:2,i:[{t:3}],s:"Керування"}},settings:{t:0,b:{t:2,i:[{t:3}],s:"Налаштування"}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:"Знайти екран"}},hint:{t:0,b:{t:2,i:[{t:3}],s:"Блимніть екраном, щоб зрозуміти, якому принтеру він належить."}},button:{t:0,b:{t:2,i:[{t:3}],s:"Знайти екран"}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:"Надіслати повідомлення"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"Введіть коротке повідомлення для показу на екрані…"}},level:{t:0,b:{t:2,i:[{t:3}],s:"Рівень"}},info:{t:0,b:{t:2,i:[{t:3}],s:"Інформація"}},warn:{t:0,b:{t:2,i:[{t:3}],s:"Попередження"}},send:{t:0,b:{t:2,i:[{t:3}],s:"Надіслати"}}},sent:{t:0,b:{t:2,i:[{t:3}],s:"Надіслано"}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:"Довідка"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Дистанційне керування — посібник"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Закрити"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Що це робить"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ця панель керує сенсорним екраном FilaMind, вбудованим у принтер: перемикає його вкладку, показує коротке повідомлення або блимає, щоб ви розпізнали потрібний принтер. Це лише команди для дисплея — вони ніколи не рухають принтер і не змінюють налаштування."}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:"Команди"}},body:{t:0,b:{t:2,i:[{t:3}],s:"«Показати» перемикає екран на вкладку «Стан», «Керування» або «Налаштування». «Знайти» блимає екраном кілька секунд. «Повідомлення» показує коротку нотатку (інформація або попередження). Команди доходять до будь-якого екрана FilaMind на цьому принтері; нічого не надсилається, поки командна шина ще підключається."}}}}},requiresScreen:{t:0,b:{t:2,i:[{t:3}],s:"Ці елементи керують екраном FilaMind на принтері. Установіть FilaMind 3D на цей принтер, щоб користуватися ними."}}}};export{t as default};
